CREATE OR REPLACE FUNCTION public.reserve_pending_order_item()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order record;
  v_product record;
  v_existing_quantity integer := 0;
  v_other_reserved integer := 0;
  v_requested integer;
begin
  select id, status, payment_status, payment_gateway, created_at, fulfillment_mode
    into v_order
    from public.orders
   where id = new.order_id;

  if found and v_order.fulfillment_mode = 'made_to_order' then
    return new;
  end if;

  if not found
     or v_order.payment_gateway <> 'razorpay'
     or v_order.payment_status <> 'pending' then
    return new;
  end if;

  if new.product_id is null or coalesce(new.quantity, 0) <= 0 then
    raise exception 'A reservable order item must reference inventory and have a positive quantity.'
      using errcode = '23514';
  end if;

  select id, name, stock_quantity
    into v_product
    from public.products
   where id = new.product_id
   for update;

  if not found then
    raise exception 'Cannot reserve a missing product.' using errcode = '23503';
  end if;

  update public.inventory_reservations
     set status = 'expired', updated_at = now()
   where product_id = new.product_id
     and status = 'active'
     and expires_at <= now();

  select coalesce(quantity, 0)
    into v_existing_quantity
    from public.inventory_reservations
   where order_id = new.order_id
     and product_id = new.product_id;

  select coalesce(sum(quantity), 0)::integer
    into v_other_reserved
    from public.inventory_reservations
   where product_id = new.product_id
     and order_id <> new.order_id
     and status = 'active'
     and expires_at > now();

  v_requested := coalesce(v_existing_quantity, 0) + new.quantity;
  if coalesce(v_product.stock_quantity, 0) - v_other_reserved < v_requested then
    raise exception 'Insufficient available stock for %.', coalesce(v_product.name, 'product')
      using errcode = 'P0001';
  end if;

  insert into public.inventory_reservations (
    order_id, product_id, quantity, status, expires_at
  ) values (
    new.order_id,
    new.product_id,
    new.quantity,
    'active',
    greatest(now(), v_order.created_at) + interval '15 minutes'
  )
  on conflict (order_id, product_id) do update
    set quantity = excluded.quantity + public.inventory_reservations.quantity,
        status = 'active',
        expires_at = excluded.expires_at,
        updated_at = now();

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_order_stock_on_create()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_previous_stock integer;
begin
  if exists (select 1 from public.orders where id = new.order_id and fulfillment_mode = 'made_to_order') then
    return new;
  end if;

  if new.product_id is null then
    return new;
  end if;

  select stock_quantity
  into v_previous_stock
  from public.products
  where id = new.product_id
  for update;

  if v_previous_stock is null then
    return new;
  end if;

  if v_previous_stock < new.quantity then
    raise exception 'Insufficient stock for product_id %', new.product_id;
  end if;

  update public.products
  set stock_quantity = stock_quantity - new.quantity
  where id = new.product_id;

  insert into public.inventory_adjustments (
    product_id,
    order_id,
    adjustment_type,
    quantity_change,
    previous_stock,
    new_stock,
    notes
  )
  values (
    new.product_id,
    new.order_id,
    'order_placed',
    -new.quantity,
    v_previous_stock,
    v_previous_stock - new.quantity,
    'Stock reduced from order placement'
  );

  return new;
end;
$function$

