CREATE OR REPLACE FUNCTION public.validate_product_classification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_main_code text;
  v_sub_category_id uuid;
begin
  select code
  into v_main_code
  from public.catalog_categories
  where id = new.main_category_id;

  if v_main_code is null then
    raise exception 'Invalid main_category_id';
  end if;

  if new.subcategory_id is not null then
    select category_id
    into v_sub_category_id
    from public.catalog_subcategories
    where id = new.subcategory_id;

    if v_sub_category_id is null then
      raise exception 'Invalid subcategory_id';
    end if;

    if v_sub_category_id <> new.main_category_id then
      raise exception 'Subcategory does not belong to selected main category';
    end if;
  end if;

  if new.option_id is not null then
    if new.subcategory_id is null then
      raise exception 'Option requires subcategory';
    end if;

    if not exists (
      select 1
      from public.catalog_options o
      where o.id = new.option_id
        and o.subcategory_id = new.subcategory_id
    ) then
      raise exception 'Option does not belong to selected subcategory';
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_product_content_rule_refs()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  v_shipping_kind public.product_content_kind;
  v_care_kind public.product_content_kind;
begin
  if new.shipping_rule_id is not null then
    select kind
    into v_shipping_kind
    from public.product_content_rules
    where id = new.shipping_rule_id;

    if v_shipping_kind is null then
      raise exception 'Invalid shipping_rule_id';
    end if;

    if v_shipping_kind <> 'shipping' then
      raise exception 'shipping_rule_id must reference a shipping rule';
    end if;
  end if;

  if new.care_warranty_rule_id is not null then
    select kind
    into v_care_kind
    from public.product_content_rules
    where id = new.care_warranty_rule_id;

    if v_care_kind is null then
      raise exception 'Invalid care_warranty_rule_id';
    end if;

    if v_care_kind <> 'care_warranty' then
      raise exception 'care_warranty_rule_id must reference a care_warranty rule';
    end if;
  end if;

  return new;
end;
$function$

